WITH exploded AS (SELECT id, log_ts, attr_key, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS attr_key, v), base AS (SELECT *, CAST(log_ts AS DATE) AS log_ts_day, DATEDIFF(CURRENT_DATE(), log_ts) AS days_since_log_ts FROM exploded WHERE attr_key IS NOT NULL), valid AS (SELECT id, log_ts, days_since_log_ts, DATE_TRUNC('month', log_ts_day) AS log_ts_day_period FROM base WHERE attr_key IS NOT NULL), enriched AS (SELECT *, CUME_DIST() OVER (ORDER BY days_since_log_ts DESC NULLS LAST) AS days_since_log_ts_cume_dist, CUME_DIST() OVER (ORDER BY days_since_log_ts NULLS LAST) AS days_since_log_ts_cume_dist_2 FROM valid WHERE log_ts < '2024-08-01'), valid_app_logs AS (SELECT id, days_since_log_ts, log_ts_day_period, ROUND(days_since_log_ts_cume_dist_2, 1) AS days_since_log_ts_cume_dist_2_rounded FROM enriched WHERE log_ts >= TO_DATE('2025-06-01') AND days_since_log_ts_cume_dist_2 <= 0.64), with_windows AS (SELECT *, MAX(days_since_log_ts_cume_dist_2_rounded) OVER (ORDER BY CAST(log_ts_day_period AS BIGINT) RANGE BETWEEN 7776000 PRECEDING AND CURRENT ROW) AS days_since_log_ts_cume_dist_2_rounded_max_90d, SUM(days_since_log_ts) OVER (ORDER BY CAST(log_ts_day_period AS BIGINT) RANGE BETWEEN 7776000 PRECEDING AND CURRENT ROW) AS days_since_log_ts_sum_90d FROM valid_app_logs), metrics AS (SELECT id, days_since_log_ts, AVG(days_since_log_ts_cume_dist_2_rounded) OVER (ORDER BY CAST(log_ts_day_period AS BIGINT) RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW) AS days_since_log_ts_cume_dist_2_rounded_avg_7d FROM with_windows), grouped AS (SELECT CASE WHEN days_since_log_ts_cume_dist_2_rounded_avg_7d >= 88 THEN 'PREMIUM' ELSE 'STANDARD' END AS days_since_log_ts_cume_dist_2_rounded_avg_7d_tier, CASE WHEN days_since_log_ts >= 77 THEN 'HIGH' ELSE 'LOW' END AS days_since_log_ts_tier, SUM(days_since_log_ts) AS total_days_since_log_ts, MAX(days_since_log_ts_cume_dist_2_rounded_avg_7d) AS max_days_since_log_ts_cume_dist_2_rounded_avg_7d, MAX(days_since_log_ts) AS max_days_since_log_ts, GROUPING(CASE WHEN days_since_log_ts_cume_dist_2_rounded_avg_7d >= 88 THEN 'PREMIUM' ELSE 'STANDARD' END) AS grouping_id FROM metrics GROUP BY GROUPING SETS ((CASE WHEN days_since_log_ts_cume_dist_2_rounded_avg_7d >= 88 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN days_since_log_ts >= 77 THEN 'HIGH' ELSE 'LOW' END), (CASE WHEN days_since_log_ts_cume_dist_2_rounded_avg_7d >= 88 THEN 'PREMIUM' ELSE 'STANDARD' END))) SELECT days_since_log_ts_cume_dist_2_rounded_avg_7d_tier, days_since_log_ts_tier, total_days_since_log_ts, max_days_since_log_ts_cume_dist_2_rounded_avg_7d, max_days_since_log_ts FROM grouped
